import json
h,w=18,15
shape={(0,2),(0,3),(1,1),(1,4)}|{(2,c) for c in range(6)}
g=[[0]*w for _ in range(h)]
for k,color in enumerate([2,3,1,8,7]):
    for dr,dc in shape:
        g[3*k+dr][3+dc]=color
assert len(g)==18 and all(len(r)==15 for r in g)
assert all(g[6+dr][3+dc]==1 for dr,dc in shape)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

